source6='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(cell for row in grid for cell in row)
    vertical = next((c for c in range(w)
                     if counts[grid[0][c]] == h and all(row[c] == grid[0][c] for row in grid)), None)
    if vertical is not None:
        width = min(vertical, w - vertical - 1)
        left = {grid[r][c] for r in range(h) for c in range(vertical)}
        right = {grid[r][vertical + 1 + c] for r in range(h) for c in range(width)}
        shared = next(iter(left & right))
        return [[3 if grid[r][c] == shared and grid[r][vertical + 1 + c] == shared else shared
                 for c in range(width)] for r in range(h)]
    horizontal = next(r for r in range(h)
                      if counts[grid[r][0]] == w and all(cell == grid[r][0] for cell in grid[r]))
    height = min(horizontal, h - horizontal - 1)
    top = {grid[r][c] for r in range(horizontal) for c in range(w)}
    bottom = {grid[horizontal + 1 + r][c] for r in range(height) for c in range(w)}
    shared = next(iter(top & bottom))
    return [[3 if grid[r][c] == shared and grid[horizontal + 1 + r][c] == shared else shared
             for c in range(w)] for r in range(height)]
'''
